"""Shared helpers for compress.py / decompress.py.

The resharded layout is:

    <output_dir>/
        manifest.json          -- describes the shard order + codec
        data/                  -- shard tree, <=30 entries per directory
            [g000/[g000/]]shard_000000.zst

The payload is a single POSIX tar stream (which encodes the full original
directory structure) piped through a streaming compressor and then cut into
fixed-size pieces.  Concatenating the pieces in manifest order reproduces the
compressed stream byte for byte.
"""

import inspect
import io
import os

MANIFEST_NAME = "manifest.json"
DATA_DIR = "data"
MAX_ENTRIES = 30  # max files or folders per directory
# 15 MB limit; stay well under both 15 * 10**6 and 15 * 2**20.
MAX_SHARD_BYTES = 13_500_000
FORMAT_VERSION = 1


# --------------------------------------------------------------------------
# codecs
# --------------------------------------------------------------------------
def _zstd_module():
    try:
        import zstandard  # noqa: F401
    except Exception:  # pragma: no cover - only when dependency is absent
        return None
    return zstandard


def available_codec():
    """Return the name of the best codec available at runtime."""
    return "zstd" if _zstd_module() is not None else "lzma"


def _supports(callable_obj, name):
    try:
        return name in inspect.signature(callable_obj).parameters
    except (TypeError, ValueError):  # pragma: no cover - C signatures
        return False


def open_compressor(codec, raw_fileobj, level=10):
    """Return a writable binary stream that compresses into ``raw_fileobj``."""
    if codec == "zstd":
        zstandard = _zstd_module()
        if zstandard is None:
            raise RuntimeError("zstandard is required to write zstd shards")
        kwargs = {"level": level}
        if _supports(zstandard.ZstdCompressor.__init__, "threads"):
            kwargs["threads"] = -1
        try:
            cctx = zstandard.ZstdCompressor(**kwargs)
        except TypeError:
            cctx = zstandard.ZstdCompressor(level=level)
        return cctx.stream_writer(raw_fileobj)
    if codec == "lzma":
        import lzma

        return lzma.open(raw_fileobj, "wb", preset=6)
    if codec == "gzip":
        import gzip

        return gzip.GzipFile(fileobj=raw_fileobj, mode="wb")
    raise ValueError("unknown codec: %r" % (codec,))


def open_decompressor(codec, raw_fileobj):
    """Return a readable binary stream decompressing ``raw_fileobj``."""
    if codec == "zstd":
        zstandard = _zstd_module()
        if zstandard is None:
            raise RuntimeError(
                "the 'zstandard' package is required to read these shards"
            )
        dctx = zstandard.ZstdDecompressor()
        try:
            return dctx.stream_reader(raw_fileobj, read_across_frames=True)
        except TypeError:
            return dctx.stream_reader(raw_fileobj)
    if codec == "lzma":
        import lzma

        return lzma.open(raw_fileobj, "rb")
    if codec == "gzip":
        import gzip

        return gzip.GzipFile(fileobj=raw_fileobj, mode="rb")
    raise ValueError("unknown codec: %r" % (codec,))


# --------------------------------------------------------------------------
# shard I/O
# --------------------------------------------------------------------------
class ShardWriter(io.RawIOBase):
    """File-like object splitting everything written into size-capped shards."""

    def __init__(self, directory, max_bytes=MAX_SHARD_BYTES, prefix="shard_"):
        super(ShardWriter, self).__init__()
        self.directory = directory
        self.max_bytes = max_bytes
        self.prefix = prefix
        self.names = []
        self._fh = None
        self._written = 0
        os.makedirs(directory, exist_ok=True)

    def writable(self):
        return True

    def _roll(self):
        if self._fh is not None:
            self._fh.close()
        name = "%s%06d" % (self.prefix, len(self.names))
        self.names.append(name)
        self._fh = open(os.path.join(self.directory, name), "wb")
        self._written = 0

    def write(self, data):
        view = memoryview(data)
        total = len(view)
        offset = 0
        while offset < total:
            if self._fh is None or self._written >= self.max_bytes:
                self._roll()
            room = self.max_bytes - self._written
            chunk = view[offset:offset + room]
            self._fh.write(chunk)
            self._written += len(chunk)
            offset += len(chunk)
        return total

    def close(self):
        if self._fh is not None:
            self._fh.close()
            self._fh = None
        super(ShardWriter, self).close()


class ConcatReader(io.RawIOBase):
    """Read a list of files as one continuous binary stream."""

    def __init__(self, paths):
        super(ConcatReader, self).__init__()
        self.paths = list(paths)
        self._index = 0
        self._fh = None

    def readable(self):
        return True

    def _next(self):
        if self._fh is not None:
            self._fh.close()
            self._fh = None
        if self._index >= len(self.paths):
            return False
        self._fh = open(self.paths[self._index], "rb")
        self._index += 1
        return True

    def read(self, size=-1):
        if size is None or size < 0:
            out = []
            while True:
                chunk = self.read(1 << 20)
                if not chunk:
                    break
                out.append(chunk)
            return b"".join(out)
        while True:
            if self._fh is None and not self._next():
                return b""
            chunk = self._fh.read(size)
            if chunk:
                return chunk
            if not self._next():
                return b""

    def readinto(self, buf):
        data = self.read(len(buf))
        buf[:len(data)] = data
        return len(data)

    def close(self):
        if self._fh is not None:
            self._fh.close()
            self._fh = None
        super(ConcatReader, self).close()


# --------------------------------------------------------------------------
# shard tree layout
# --------------------------------------------------------------------------
def shard_tree_paths(count, max_entries=MAX_ENTRIES):
    """Relative (posix) paths for ``count`` shards, <=max_entries per folder."""
    if count == 0:
        return []
    depth = 1
    while max_entries ** depth < count:
        depth += 1
    paths = []
    for i in range(count):
        parts = []
        for level in range(depth - 1, 0, -1):
            parts.append("g%03d" % (i // (max_entries ** level) % max_entries))
        parts.append("shard_%06d" % i)
        paths.append("/".join(parts))
    return paths

